
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_pbeh_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_pbeh", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.291768611712875e+00, -3.229439664585390e+00, -3.142150429134156e+00, -3.021336883297711e+00, -2.856936212524515e+00, -2.638615469576289e+00, -2.358665911183728e+00, -2.017189515845104e+00, -1.628720707352263e+00, -1.223036149745063e+00, -8.264513405313677e-01, -5.697092736866536e-01, -4.974911356043539e-01, -4.077377807019651e-01, -2.936247326735733e-01, -1.857860925662735e-01, -1.002177773394249e-01, -3.714278170170081e-02, -8.108947346529199e-03, -9.121516116720762e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


